<?php namespace App\Livewire\Vendor; use App\Actions\UpdateOrderStatusAction; use App\Models\Order; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class ManageOrders extends Component { use AuthorizesRequests; public ?int $selectedOrderId = null; public string $newStatus = 'Preparing'; public function selectOrder(int $orderId): void { $order = Order::findOrFail($orderId); $this->authorize('view', $order); $this->selectedOrderId = $order->id; $this->newStatus = $order->status; } public function updateStatus(UpdateOrderStatusAction $action): void { if (!$this->selectedOrderId) return; $order = Order::findOrFail($this->selectedOrderId); $this->authorize('updateStatus', $order); $action->execute($order, $this->newStatus, null); session()->flash('status', 'Order #' . $order->id . ' updated to ' . $this->newStatus . '.'); } public function togglePayment(int $orderId, UpdateOrderStatusAction $action): void { $order = Order::findOrFail($orderId); $this->authorize('updateStatus', $order); $nextPayment = $order->payment_status === 'Paid' ? 'Unpaid' : 'Paid'; $action->execute($order, null, $nextPayment); session()->flash('status', 'Order #' . $order->id . ' marked as ' . $nextPayment . '.'); } public function render() { $stall = auth()->user()->stall; $orders = $stall ? Order::with(['user', 'orderItems.foodItem'])->where('stall_id', $stall->id)->latest()->get() : collect(); $selectedOrder = $this->selectedOrderId ? $orders->firstWhere('id', $this->selectedOrderId) : $orders->first(); if ($selectedOrder && !$this->selectedOrderId) { $this->selectedOrderId = $selectedOrder->id; $this->newStatus = $selectedOrder->status; } return view('livewire.vendor.manage-orders', ['stall' => $stall, 'orders' => $orders, 'selectedOrder' => $selectedOrder]); } }